import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'
import {patternConfigsPageRoute} from './pattern-configs-page-route'
import {PatternConfigsPage} from '../components/PatternConfigsPage'

export function OrgRoute() {
  const payload = useRouteQuery(patternConfigsPageRoute, 'mainQuery').data
  const {org} = useRouteParams(patternConfigsPageRoute)
  return (
    <PatternConfigsPage payload={payload} ownerType="org" updatePath={patternConfigsPageRoute.generatePath({org})} />
  )
}
