import {useId, useMemo, useState} from 'react'
import {useMutation} from '@github-ui/react-query'
import {useSearchParams} from '@github-ui/use-navigate'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {Filter} from '@github-ui/filter'
import {CheckIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Breadcrumbs, Label, Link} from '@primer/react'
import {DataTable, Table, type Column} from '@primer/react/experimental'
import {BoolSetting} from '@github-ui/secret-scanning/types/settings'
import {Button, DismissibleBanner} from '@github-ui/secret-scanning/components'
import {toPercentInt, toPercentString} from '@github-ui/secret-scanning/utils'
import type {PatternConfigsPageResponse} from '../routes/pattern-configs-page-route'
import type {PatternOverride, PatternSetting} from '../types'
import {defaultActiveTab, PatternConfigTabs, type PatternConfigTabName} from './PatternConfigsTabBar'
import {resolveNotSetLongText, resolveNotSetShortText} from '../utils'
import {
  FilterProperty,
  GitHubDefaultFilter,
  InheritedStateFilter,
  isFilterProperty,
  NameFilter,
  PushProtectionSettingFilter,
  AlertTotalPercentageFilter,
  AlertTotalFilter,
  FalsePositiveRateFilter,
  FalsePositivesFilter,
  BypassRateFilter,
} from '../models/filters'
import {SortDirection, SortPatternOverrides, SortProperty} from '../models/sorting'

const SearchParams = {
  Tab: 'tab',
  Page: 'page',
  Query: 'query',
  SortColumn: 'sort-column',
  SortDirection: 'sort-direction',
} as const

// TODO move to components/ folder
export function PatternConfigsPage({
  payload,
  ownerType,
  updatePath,
}: {
  payload: PatternConfigsPageResponse
  ownerType: 'org' | 'biz'
  updatePath: string
}) {
  const [searchParams, _setSearchParams] = useSearchParams()
  function setSearchParams(newSearchParams: Record<string, string>) {
    _setSearchParams(
      prev => {
        for (const [key, value] of Object.entries(newSearchParams)) {
          prev.set(key, value)
        }
        return prev
      },
      {preventScrollReset: true},
    )
  }

  const MAX_NAME_COLUMN_WIDTH = '380px'
  const patternConfig = payload.pattern_config
  const [providerOverrides, setProviderOverrides] = useState(patternConfig.provider_pattern_overrides)
  const [customPatternOverrides, setCustomPatternOverrides] = useState(patternConfig.custom_pattern_overrides)

  const [rowVersion, setRowVersion] = useState(patternConfig.row_version)
  const [configNumber, setConfigNumber] = useState(patternConfig.number)

  const selectedTab = (searchParams.get(SearchParams.Tab) as PatternConfigTabName) || defaultActiveTab
  const [selectedProviderSettings, setSelectedProviderSettings] = useState(() => new Map<string, PatternSetting>())
  const [selectedCustomPatternSettings, setSelectedCustomPatternSettings] = useState(
    () => new Map<string, PatternSetting>(),
  )

  const sortColumn = (searchParams.get(SearchParams.SortColumn) as SortProperty) || SortProperty.Name
  const sortDirection = (searchParams.get(SearchParams.SortDirection) as SortDirection) || SortDirection.Ascending

  const page = parseInt(searchParams.get(SearchParams.Page) || '0')
  const pageSize = 15
  let selectedOverrides = providerOverrides
  let selectedSettings = selectedProviderSettings
  let setSelectedSettings = setSelectedProviderSettings
  if (selectedTab === 'custom') {
    selectedOverrides = customPatternOverrides
    selectedSettings = selectedCustomPatternSettings
    setSelectedSettings = setSelectedCustomPatternSettings
  }

  const mutation = useMutation({
    mutationFn: async () => {
      const res = await reactFetchJSON(updatePath, {
        method: 'PATCH',
        body: {
          number: configNumber,
          row_version: rowVersion,
          provider_pattern_settings: Array.from(selectedProviderSettings.values()),
          custom_pattern_settings: Array.from(selectedCustomPatternSettings.values()),
        },
      })
      if (!res.ok) {
        throw new Error('Failed to update pattern settings')
      }
      const data = await res.json()
      setRowVersion(data.row_version)
      setConfigNumber(data.number)
    },
    onSuccess: () => {
      // Reset state so new changes are the new initial
      setProviderOverrides(prev => {
        return prev.map(row => {
          const newSetting = selectedProviderSettings.get(row.id)
          if (newSetting) {
            return {
              ...row,
              setting: newSetting?.push_protection_setting ?? row.setting,
            }
          }
          return row
        })
      })
      setCustomPatternOverrides(prev => {
        return prev.map(row => {
          const newSetting = selectedCustomPatternSettings.get(row.id)
          if (newSetting) {
            return {
              ...row,
              setting: newSetting?.push_protection_setting ?? row.setting,
            }
          }
          return row
        })
      })
      setSelectedProviderSettings(new Map())
      setSelectedCustomPatternSettings(new Map())
    },
  })

  const filterQueryString = searchParams.get(SearchParams.Query)
  const activeFilters = useMemo(() => parseQueryString(filterQueryString), [filterQueryString])
  const start = page * pageSize
  const end = start + pageSize
  const filteredOverrides = selectedOverrides.filter(patternOverride => {
    return activeFilters.every(({property, value, excluded}) => {
      switch (property) {
        case FilterProperty.Name:
          return satisfiesTextFilter(patternOverride.display_name, value, excluded)
        case FilterProperty.GitHubDefault:
          return satisfiesFilter(patternOverride.default_setting, value, excluded)
        case FilterProperty.InheritedState:
          return satisfiesFilter(patternOverride.inherited_setting, value, excluded)
        case FilterProperty.PushProtectionSetting:
          return satisfiesFilter(patternOverride.setting, value, excluded)
        case FilterProperty.AlertTotalPercentage: {
          const alertTotalPercentage = toPercentInt(patternOverride.alert_total, patternConfig.total_alerts)
          return satisfiesNumberFilter(alertTotalPercentage, value, excluded)
        }
        case FilterProperty.AlertTotal:
          return satisfiesNumberFilter(patternOverride.alert_total, value, excluded)
        case FilterProperty.FalsePositiveRate: {
          const falsePositiveRate = toPercentInt(patternOverride.false_positives, patternOverride.alert_total)
          return satisfiesNumberFilter(falsePositiveRate, value, excluded)
        }
        case FilterProperty.FalsePositives:
          return satisfiesNumberFilter(patternOverride.false_positives, value, excluded)
        case FilterProperty.BypassRate: {
          const bypassRate = toPercentInt(patternOverride.bypasses, patternOverride.blocks)
          return satisfiesNumberFilter(bypassRate, value, excluded)
        }
        default:
          property satisfies never
      }
    })
  })
  const sortedOverrides = SortPatternOverrides(filteredOverrides, sortColumn, sortDirection)
  const data = sortedOverrides.slice(start, end)
  const columns: Array<Column<PatternOverride>> = [
    {
      header: 'Name',
      field: 'display_name',
      renderCell: row => {
        const alertsLinkEnabled = isFeatureEnabled('secret_scanning_pattern_alerts_link')
        if (alertsLinkEnabled && payload.secret_scanning_alerts_path) {
          const href = `${payload.secret_scanning_alerts_path}?query=secret-type:${encodeURIComponent(row.slug)}`
          return (
            <Link data-testid="display-name" href={href}>
              {row.display_name}
            </Link>
          )
        }
        return <span data-testid="display-name">{row.display_name}</span>
      },
      sortBy: true,
      id: SortProperty.Name,
      maxWidth: MAX_NAME_COLUMN_WIDTH,
    },
    {
      header: 'Alert total',
      field: 'alert_total',
      align: 'end',
      renderCell: row => {
        return `${toPercentString(row.alert_total, patternConfig.total_alerts)} (${row.alert_total.toLocaleString()})`
      },
      sortBy: true,
      id: SortProperty.AlertTotal,
    },
    {
      header: 'False positives',
      field: 'false_positives',
      align: 'end',
      renderCell: row => {
        return `${toPercentString(row.false_positives, row.alert_total)} (${row.false_positives.toLocaleString()})`
      },
      sortBy: () => {
        return 0 // The table will try to sort the page individually based on the false_positives raw number value, to prevent this we override the sort the table uses so it will just respect our input order
      },
      id: SortProperty.FalsePositiveRate,
    },
    {
      header: 'Bypass rate',
      field: 'bypasses',
      align: 'end',
      renderCell: row => {
        return toPercentString(row.bypasses, row.blocks)
      },
      sortBy: () => {
        return 0 // The table will try to sort the page individually based on the bypasses raw number value, to prevent this we override the sort the table uses so it will just respect our input order
      },
      id: SortProperty.BypassRate,
    },
  ]
  if (selectedTab === 'native') {
    columns.push({
      header: 'GitHub default',
      field: 'default_setting',
      renderCell: row => {
        return <span data-testid="default-setting">{boolSettingToString(row.default_setting, 'Unknown')}</span>
      },
    })
    if (payload.has_parent) {
      columns.push({
        header: 'Enterprise setting',
        field: 'inherited_setting',
        renderCell: row => {
          return (
            <span data-testid="inherited-setting">{boolSettingToString(row.inherited_setting, 'GitHub default')}</span>
          )
        },
      })
    }
  }
  columns.push({
    header: ownerType === 'org' ? 'Organization setting' : 'Enterprise setting',
    field: 'setting',
    renderCell: row => {
      const currentSetting = selectedSettings.get(row.id)?.push_protection_setting
      return (
        <SettingActionMenu
          row={row}
          isProviderPattern={selectedTab === 'native'}
          hasParent={payload.has_parent}
          currentSetting={currentSetting}
          onSelect={result => {
            if (result.isResetToInitial) {
              setSelectedSettings(prev => {
                const newMap = new Map(prev)
                newMap.delete(result.setting.token_type)
                return newMap
              })
            } else {
              setSelectedSettings(prev => new Map(prev.set(result.setting.token_type, result.setting)))
            }
          }}
        />
      )
    },
  })

  const filterProviders = [
    new NameFilter(),
    new AlertTotalFilter(),
    new AlertTotalPercentageFilter(),
    new FalsePositiveRateFilter(),
    new FalsePositivesFilter(),
    new BypassRateFilter(),
    new GitHubDefaultFilter(),
  ]
  if (payload.has_parent) {
    filterProviders.push(new InheritedStateFilter())
  }
  filterProviders.push(
    new PushProtectionSettingFilter({hasParent: payload.has_parent, isEnterprise: ownerType === 'biz'}),
  )

  const headingId = useId()
  const subHeadingId = useId()
  return (
    <>
      <Breadcrumbs className="mb-2">
        <Breadcrumbs.Item as={Link} href={payload.security_settings_path}>
          {ownerType === 'org' ? 'Global settings' : 'Advanced security'}
        </Breadcrumbs.Item>
        <Breadcrumbs.Item selected>Pattern configurations</Breadcrumbs.Item>
      </Breadcrumbs>
      <h2 data-hpc className="h3" id={headingId}>
        Pattern configuration
      </h2>
      <p className="mb-2" id={subHeadingId}>
        Configure push protection enablement by pattern. Passwords detected with AI are not supported.
      </p>
      <hr className="mt-0 tmp-mb-3" />

      {mutation.isSuccess && (
        <DismissibleBanner className="tmp-mb-3" variant="success" icon={<CheckIcon />} title="Success" hideTitle>
          Your changes have been applied.
        </DismissibleBanner>
      )}
      {mutation.isError && (
        <DismissibleBanner className="tmp-mb-3" variant="critical" title="Error" hideTitle>
          Failed to update pattern settings. Please try again later.
        </DismissibleBanner>
      )}

      <Filter
        className="tmp-mb-3"
        id="pattern-configs-filter"
        label="Pattern configurations filter"
        initialFilterValue={filterQueryString || undefined}
        onChange={queryString => {
          setSearchParams({
            [SearchParams.Query]: queryString,
            [SearchParams.Page]: '0',
          })
        }}
        providers={filterProviders}
      />

      <PatternConfigTabs
        activeTab={selectedTab}
        setSelectedTab={tabName => {
          setSearchParams({
            [SearchParams.Tab]: tabName,
            [SearchParams.Page]: '0',
          })
        }}
        customPatternsCount={customPatternOverrides.length}
      />

      <Table.Container>
        <DataTable
          aria-labelledby={headingId}
          aria-describedby={subHeadingId}
          data={data}
          columns={columns}
          initialSortColumn={sortColumn}
          initialSortDirection={sortDirection}
          onToggleSort={(columnID, direction) => {
            setSearchParams({
              [SearchParams.SortColumn]: columnID.toString(),
              [SearchParams.SortDirection]: direction,
            })
          }}
        />
        <Table.Pagination
          key={selectedTab + activeFilters.reduce((acc, filter) => acc + filter.property + filter.value, '')}
          aria-label="Pagination for pattern configs"
          totalCount={filteredOverrides.length}
          pageSize={pageSize}
          // Need to set index to undefined if there's no custom patterns
          defaultPageIndex={selectedTab === 'custom' && customPatternOverrides.length < 1 ? undefined : page}
          onChange={({pageIndex: newPageIndex}) => {
            // Without the timeout, a weird error occurs: "Cannot update a component (`RouterProvider`) while rendering a different component (`Pagination`)".
            setTimeout(() => {
              setSearchParams({
                [SearchParams.Page]: newPageIndex.toString(),
              })
            })
          }}
        />
      </Table.Container>
      <div className="d-flex gap-2 tmp-mt-3">
        <Button
          variant="primary"
          inactive={selectedCustomPatternSettings.size + selectedProviderSettings.size === 0}
          loading={mutation.isPending}
          onClick={() => mutation.mutate()}
        >
          Apply changes
        </Button>
        <Button
          inactive={selectedCustomPatternSettings.size + selectedProviderSettings.size === 0 || mutation.isPending}
          onClick={() => {
            setSelectedProviderSettings(new Map())
            setSelectedCustomPatternSettings(new Map())
          }}
        >
          Cancel
        </Button>
      </div>
    </>
  )
}

function SettingActionMenu({
  row,
  currentSetting,
  isProviderPattern,
  hasParent,
  onSelect,
}: {
  row: PatternOverride
  currentSetting?: BoolSetting
  isProviderPattern: boolean
  hasParent: boolean
  onSelect: (setting: {setting: PatternSetting; isResetToInitial: boolean}) => void
}) {
  const initialSetting = row.setting
  const setting = currentSetting ?? row.setting
  function handleSettingChange(newSetting: BoolSetting) {
    onSelect({
      setting: {
        token_type: row.id,
        push_protection_setting: newSetting,
        row_version: row.row_version,
      },
      isResetToInitial: newSetting === initialSetting,
    })
  }

  return (
    <ActionMenu>
      {/* minWidth to get "Enabled" button to be same size as other buttons */}
      <ActionMenu.Button data-testid="push-protection-setting" style={{minWidth: '114px'}} alignContent="start">
        {boolSettingToString(setting, resolveNotSetShortText({hasParent}))}
      </ActionMenu.Button>
      <ActionMenu.Overlay width="small">
        <ActionList selectionVariant="single">
          <ActionList.Item
            selected={setting === BoolSetting.Enabled}
            aria-checked={setting === BoolSetting.Enabled}
            onSelect={() => handleSettingChange(BoolSetting.Enabled)}
          >
            Enabled
          </ActionList.Item>
          <ActionList.Item
            selected={setting === BoolSetting.Disabled}
            aria-checked={setting === BoolSetting.Disabled}
            onSelect={() => handleSettingChange(BoolSetting.Disabled)}
          >
            Disabled
          </ActionList.Item>
          {isProviderPattern && (
            <ActionList.Item
              selected={setting === BoolSetting.NotSet}
              aria-checked={setting === BoolSetting.NotSet}
              onSelect={() => handleSettingChange(BoolSetting.NotSet)}
            >
              <span className="text-normal">{resolveNotSetLongText({hasParent})}</span>
              <ActionList.TrailingVisual>
                <Label>
                  {boolSettingToString(hasParent ? row.inherited_setting : row.default_setting, 'GitHub default')}
                </Label>
              </ActionList.TrailingVisual>
              <ActionList.Description variant="block">
                {hasParent ? 'Inherit enterprise setting' : "This state may change based on GitHub's recommendations"}
              </ActionList.Description>
            </ActionList.Item>
          )}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

function boolSettingToString(setting: BoolSetting, notSetText: string): string {
  switch (setting) {
    case BoolSetting.Enabled:
      return 'Enabled'
    case BoolSetting.Disabled:
      return 'Disabled'
    case BoolSetting.NotSet:
      return notSetText
    default:
      return setting satisfies never
  }
}

function parseQueryParam(param: string | null | undefined) {
  if (!param) return
  const splitted = param.split(':')
  let property = splitted[0]?.trim()
  const value = splitted[1]?.trim()
  if (!property || !value) return

  const excluded = property.startsWith('-')
  if (excluded) {
    property = property.slice(1)
  }

  if (!isFilterProperty(property)) return
  const filter: QueryFilter = {property, value, excluded}
  return filter
}

function satisfiesFilter<T>(property: T, value: T, exclude: boolean): boolean {
  if (exclude) {
    return property !== value
  } else {
    return property === value
  }
}

function satisfiesTextFilter(property: string, value: string, exclude: boolean): boolean {
  property = property.toLowerCase()
  value = value.toLowerCase()
  if (value.startsWith('"') && value.endsWith('"')) {
    // If the value is wrapped in quotes, we treat it as an exact match
    value = value.slice(1, -1)
  }
  if (exclude) {
    return !property.includes(value)
  } else {
    return property.includes(value)
  }
}

const allowedFilterOperators = ['<=', '>=', '<', '>'] // Note: these operators need to be in order of length for correct parsing
function satisfiesNumberFilter(property: number, value: string, exclude: boolean): boolean {
  const parsed = parseInt(value, 10)
  if (!isNaN(parsed)) {
    // If value is a number, we can compare directly
    if (exclude) {
      return property !== parsed
    } else {
      return property === parsed
    }
  }
  // If value is not a number, we check for operators
  const operator = allowedFilterOperators.find(op => value.startsWith(op))
  if (operator) {
    const numberValue = parseInt(value.slice(operator.length).trim(), 10)
    if (isNaN(numberValue)) return false // Invalid number after operator

    switch (operator) {
      case '<':
        return exclude ? property >= numberValue : property < numberValue
      case '>':
        return exclude ? property <= numberValue : property > numberValue
      case '<=':
        return exclude ? property > numberValue : property <= numberValue
      case '>=':
        return exclude ? property < numberValue : property >= numberValue
      default:
        return false // Should not happen, but just in case
    }
  }
  return false // No valid comparison found
}

interface QueryFilter {
  property: FilterProperty
  value: string
  excluded: boolean
}

function parseQueryString(queryString?: string | null) {
  if (!queryString) return []
  // Match against a space-separated query, where the items can be either:
  // - A quoted value, `name:"hello world"`
  // - A non-whitespace string, `name:hello-world` (also matches just `name`, but it gets ignored in parsing due to lacking the value)
  const queryRegexResult = queryString.matchAll(/(\S+:".+?"|[^"]\S+)\s*/g)
  return Array.from(queryRegexResult)
    .map(regexResult => {
      const parsed = parseQueryParam(regexResult[1])
      if (!parsed) return
      return parsed
    })
    .filter((it): it is NonNullable<typeof it> => !!it)
}
