import {GlobeIcon, HashIcon, MarkGithubIcon, OrganizationIcon, PencilIcon} from '@primer/octicons-react'
import {NumericFilterProvider, SelectFilterProvider, StaticFilterProvider} from '@github-ui/filter-core/providers'
import {BoolSetting} from '@github-ui/secret-scanning/types/settings'
import {resolveNotSetLongText} from '../utils'
import {FilterProviderType} from '@github-ui/filter-core'

export const FilterProperty = {
  Name: 'name',
  GitHubDefault: 'github-default',
  InheritedState: 'enterprise-setting',
  PushProtectionSetting: 'organization-setting',
  AlertTotalPercentage: 'alert-total-percentage',
  AlertTotal: 'alert-total',
  FalsePositiveRate: 'false-positive-rate',
  FalsePositives: 'false-positives',
  BypassRate: 'bypass-rate',
} as const
export type FilterProperty = (typeof FilterProperty)[keyof typeof FilterProperty]
export function isFilterProperty(property: string): property is FilterProperty {
  return Object.values(FilterProperty).includes(property as FilterProperty)
}

export class NameFilter extends StaticFilterProvider {
  constructor() {
    super(
      {
        key: FilterProperty.Name,
        displayName: 'Name',
        priority: 1,
        icon: PencilIcon,
      },
      [],
      {filterTypes: {valueless: false, multiValue: true}},
    )
    this.type = FilterProviderType.Text
  }
}

