export class PushProtectionSettingFilter extends SelectFilterProvider {
  constructor({hasParent, isEnterprise}: {hasParent: boolean; isEnterprise: boolean}) {
    super(
      {
        key: FilterProperty.PushProtectionSetting,
        displayName: isEnterprise ? 'Enterprise setting' : 'Organization setting',
        priority: 1,
        icon: isEnterprise ? GlobeIcon : OrganizationIcon,
      },
      [
        {
          value: BoolSetting.Enabled,
          displayName: 'Enabled',
          priority: 1,
        },
        {
          value: BoolSetting.Disabled,
          displayName: 'Disabled',
          priority: 2,
        },
        {
          value: BoolSetting.NotSet,
          displayName: resolveNotSetLongText({hasParent}),
          priority: 3,
        },
      ],
      {filterTypes: {valueless: false}},
    )
  }
}
